pub(crate) fn stop_cut(&self, requested: i64) -> i64 {
        self.cut.unwrap_or(i64::MAX).min(requested.max(self.progress))
    }

    pub(crate) fn book_cut(&mut self, cut: i64) {
        self.cut = Some(cut);
        self.cancel_queued(|e| e >= cut);
        self.revision += 1;
    }

